-- Splynn Dimensional Market: the book's 11 Bio-Wizard symbiotes, Aqua-Mask to Zembahk Appendage, printed 128-137.
-- 11 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~360-splynn-symbiotes.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('aqua-mask', 'Aqua-Mask (Symbiote)', 'rifts', 'magic', NULL, 300000, '300,000 credits; commonly handed to land-dwelling Splugorth Minions whose missions may take them underwater', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A Bio-Wizard diving organism, first bred to make Aquarobe micro-organisms, that is pulled on over the face like a mask. Mortal hosts only (humans, D-Bees and the like); no M.D.C. creature, supernatural being or creature of magic can take it. Engineered sterile, so new ones are cloned. 1D4x10 Hit Points, a three-month life span, low animal intelligence. It fills the lungs with Aquarobes so the host breathes water like a fish, filters out pollutants, lets him swim at 98% and gives him sonar; he can dive to twice his normal depth tolerance, about 300 ft (91.5 m) for a human. +2 to save vs poisons and +2 dodge underwater, and he functions underwater without sight. The catch: it covers the whole face and blinds him. Sonar shows shapes and distances underwater but no colours, painted insignia, symbols or fine detail. Head-sized, though it can be grown twice as large. It can be taken off at any time with no ill effect (underwater is another matter). It ignores other organisms. Longer underwater missions usually go to power-armored Minions, Slavers or Metzla instead.', 'Rifts World Book 21: Splynn Dimensional Market p.128', NULL),
  ('electrone', 'Electrone (Symbiote)', 'rifts', 'magic', NULL, 1000000, '1 million credits for one; a mated pair costs ten times as much, since its young sell wholesale for 250,000 to 300,000 credits each', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A beetle-like organism, its body 4 inches (101 mm) long and half as wide, whose legs become tentacles that wrap the torso or an arm and sink deep into the flesh, pulsing the host''s own bio-electric field up to striking levels. Mortal hosts only, never a supernatural being, creature of magic or M.D.C. creature. 5D6 M.D.C., about twenty years once bonded (some last twice that), low animal intelligence. It can breed once a year but seldom gets the chance: the host must come within 1 ft (0.3 m) of someone wearing one of the opposite sex, or wear a mated pair himself (one per arm, an arm and the torso, or both arms and the torso); extra Electrones add no bonuses, power or damage. After a month bonded the host gains: Jolt Touch, 1D4 to 1D4x10 S.D.C. in 1D4 steps, one melee attack per touch, or a 1D6 M.D. touch once per melee round; Electric Bolt (arm-bonded only, from that arm), 1D4 to 3D4 S.D.C. in 1D4 steps per attack, or a 1D4 M.D. bolt once per melee round, range 200 ft (61 m); Electric Recharge of batteries, small ones in one melee and an E-clip in an hour (10 blasts), with no other electric power usable then or for 2D6 minutes after; Electric Aura (torso-bonded only), a one-minute field doing 1D6x10 S.D.C. to whoever touches him once every other minute, or 2D6 M.D. once an hour, with half damage from electric attacks while it lasts. +2 initiative, +2 parry and dodge, +1 roll with punch or impact, -1 to pull punch. He draws lightning and electric arcs: such attacks aimed at him are +2 to strike, and stray strikes seek him out. A constant static charge gathers dust, rustles papers and tingles anyone who touches him. Surgery is easy and harmless if done right; a failed roll goes to the Surgery Penalty Table for body organisms, Rifts Atlantis p.114. Killing it may do lasting harm and releases 3D6 M.D. to everything within 10 ft (3 m). It ignores other organisms, but an Elom symbiote cancels its powers and halves its life.', 'Rifts World Book 21: Splynn Dimensional Market p.128-129', NULL),
  ('line-feeder', 'Line Feeder (Symbiote)', 'rifts', 'magic', NULL, 300000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A fat black slug 5 inches (127 mm) long that clings like a barnacle anywhere on the host, ideally the torso, in exchange for trips to a ley line. Any mobile living creature can host it. It mates as often as every four months, one young each time. 2D6 Hit Points; up to ten years with regular feeding, about five as a rule; low animal intelligence. It psionically lets the host sense ley lines and nexus points as a Ley Line Walker does, at 4th-level proficiency, but not Rifts or magic energy, and warns him of a ley line storm 2D6 minutes before it breaks. No bonuses and no side effects beyond wearing it. Tearing it off ends everything with no lasting harm, though it stings like stripping duct tape: 1D4 S.D.C. It ignores other organisms, but a Mystic Leech drains it to death within 1D4 days.', 'Rifts World Book 21: Splynn Dimensional Market p.129-130', NULL),
  ('musical-nymph', 'Musical Nymph (Symbiote)', 'rifts', 'magic', NULL, 50000, '50,000 credits; popular with slave dealers, though the taming wears off in a few months', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An insect larva, like a maggot an eighth of an inch (3 mm) long, that lives in the inner ear and hums its host calm yet alert. Used mostly on wild animals, monsters and unruly slaves, sometimes by warriors. Humans, D-Bees and other mortals, M.D.C. D-Bees and creatures included; never supernatural beings or creatures of magic. One Hit Point; three months as a larva in the host, then up to a month on the wing hunting a mate, the pair laying up to 3D6 eggs just before dying. Low animal intelligence. Strong emotions such as fear and hate lose their grip: frenzies and rages build at half speed and burn out in half the time, emotion-inducing magic and psionics have half their effect, duration and penalties, and even a species'' natural aggression or berserking is dulled. +3 on saves against Horror Factor, Empathic Transmission, magical fears and the like, +1 initiative, and no skill penalties under stress. Joy, love and other strong feelings are blunted too, leaving him a little dull and flat. Killing it removes it with no lasting effect. It ignores other organisms. Once it leaves, a tamed animal or slave drifts back to its old wild or violent ways.', 'Rifts World Book 21: Splynn Dimensional Market p.130-131', NULL),
  ('storm-breather', 'Storm Breather (Symbiote)', 'rifts', 'magic', NULL, 1500000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'One of two Bio-Wizard variants of a small symbiote from a dust-choked world of deep valleys, where it raised winds to keep its host''s lungs clear; it sits on the neck around the throat. Mortal hosts only, never an M.D.C. creature, supernatural being or creature of magic. The variant is sterile and each one is altered from the wild stock (whose males release spore-like sperm on the air). 2D6 Hit Points, two-year life span, low animal intelligence. At will and with no P.P.E. cost, the host breathes Air Elemental spells of the same names from his mouth: Lightning Breath, 2D6 M.D., once per melee round (15 seconds), range 200 ft (61 m); Blizzard Breath, as Northwind, once per melee, 200 ft (61 m) in a 45 degree cone; Wind Rush, once per melee, 120 ft (36.6 m); Whisper of the Wind and Fingers of Wind, each as often as his hand to hand attacks per melee, at line of sight up to 2000 ft (610 m) and at 90 ft (28 m) respectively. No bonuses. It leaves him mute, speaking only through Whisper of the Wind: no radios or other audio gear, spoken spells all but useless, and no talking to anyone inside a robot or heavy vehicle unless a door is opened. About the size of an outstretched hand. Surgery done right does no lasting harm; a failed attempt, or killing it, leaves a 01-50% chance he stays mute or can manage only a low, husky whisper. If it dies naturally his voice comes back whole. It ignores other organisms, though nothing else can use the throat while it is there.', 'Rifts World Book 21: Splynn Dimensional Market p.131', NULL),
  ('solara', 'Solara (Symbiote)', 'rifts', 'magic', NULL, 2500000, '2.5 million credits on average; the book says one may be seen on sale for five million', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'An energy being from a world where every creature glittered in the sun, now a Splynn fashion among owners who want their slaves, dancers and gladiators to sparkle. Any mortal host, Mega-Damage beings included; never supernatural beings or creatures of magic. It wraps the whole body in soft light by day and lies within it at night. At the end of its life it bursts harmlessly into a hundred motes that re-form minutes later as 1D4 new Solara, one usually staying with the old host. A Mega-Damage creature of 1D4x10 M.D.C., hurt only by weapons made to harm energy beings and otherwise proof against radiation, heat, lightning, lasers and most energy weapons, a resistance the host does not share. Lives about 4 to 4.5 years; usually unprincipled or anarchist with little ambition; high animal intelligence. By day it shines as an aura about a foot (0.3 m) out from him; at night he glows from within. In full daylight: +2 M.A., P.E. and P.B., +1D4x10 S.D.C. (2D6 M.D.C. for a mortal M.D.C. being), +5% to save vs coma/death, +1 initiative and an air of confidence. All of it fades in the hour before dusk, and from an hour after sunset it feeds on him instead of the sun: -1 P.S., -4 Spd, -1 parry and dodge, and a loss of 2D6 S.D.C. (1D4 M.D.C. for an M.D.C. being), until an hour after dawn, the bonuses returning later. Bright artificial light spares him the penalties but grants no bonuses. Glowing people tend to be taken for wizards and draw trouble. Being immaterial it cannot be cut out; Purge Self or Purge Other expels it at once and exorcism works 01-50% of the time, though most hosts, slaves included, like having it. It ignores other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.131, 133', NULL),
  ('storm-screamer', 'Storm Screamer (Symbiote)', 'rifts', 'magic', NULL, 1200000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'The Storm Breather''s sister variant, all but identical to look at, worn on the neck around the throat but with sound-based powers. Mortal hosts only, never an M.D.C. creature, supernatural being or creature of magic. Sterile, each one altered from the wild stock. 2D6 Hit Points, two-year life span, low animal intelligence. At will and with no P.P.E. cost, projected from the mouth: Sonic Scream, as the Sonic Blast spell of Rifts Federation of Magic, 3D6 M.D., once per melee round, 20 ft (6.1 m) in a 45 degree cone; Thunder Roar, as Thunderclap, once per melee round, audible up to a mile (1.6 km) off; Howling Wind, once per melee, 100 ft (30.5 m) in a 45 degree cone; and Ultrasonic Speech, pitched so only Dog Boys, some D-Bees, mutants, animals and those with an Ultra-Ear implant can hear it. No bonuses. Otherwise he is mute, and must sign, use telepathy or find some other way to reach most people. About the size of an outstretched hand. Surgery done right does no lasting harm; a failed attempt, or killing it, leaves a 01-50% chance he stays mute. If it dies naturally his voice returns. It ignores other organisms, though nothing else can use the throat while it is there.', 'Rifts World Book 21: Splynn Dimensional Market p.133-134', NULL),
  ('symbiotic-heart', 'Symbiotic Heart (Symbiote)', 'rifts', 'magic', NULL, 2000000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A living heart surgically put in place of the host''s own, which it outperforms. Humans, D-Bees and other mortals; never supernatural beings or creatures of magic. Hearts mate once a year before bonding, one young at a time; the artificial bonding stops further mating. 4D6 Hit Points; five years unbonded, and as long as the host once bonded. Alignment not applicable. +5% vs coma and death, +3 P.E., +1 to save vs Horror Factor; the equivalent of the psionic Summon Inner Strength up to ten times in 24 hours with no I.S.P. cost; he tires at half the usual rate, gets by on 4-5 hours of sleep, and is immune to most heart disease and clogged arteries. No side effects. Roughly the size of a human heart (anywhere from half to twice that, matched to the host). Taking it out works but kills him unless a replacement heart is ready. It ignores most other organisms, except that Heart Worm parasites eat it as they would a real heart.', 'Rifts World Book 21: Splynn Dimensional Market p.134', NULL),
  ('thundergut', 'Thundergut (Symbiote)', 'rifts', 'magic', NULL, 1500000, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A worm swallowed through the mouth that lives in the stomach and intestines, trading lodging for strength and stamina; in the wild it bonds only to carnivores. Mortal hosts only, never an M.D.C. creature, supernatural being or creature of magic. It enters a host soon after birth, stays until mature, is then coughed up to find a mate and has 1D6 young. 2D6+2 Hit Points; three years of life, two of them inside a host; low animal intelligence. +1D6 P.S., +1D4 P.E., +6 on saves against poison and stomach disease, and +1D4x10 S.D.C.. It needs raw meat: at least a pound (.45 kg) a day, or the added P.S. and P.E. drop by 1 a day, and after a week unfed it dies and is expelled with every bonus. Earthworm-sized at about 3 inches (76 mm) going in, roughly five times that length coming out, and very hard to bring up. Surgery does no lasting harm unless botched, when the roll goes to the Surgery Penalty Table for body organisms, Rifts Atlantis p.114. It ignores most organisms, but attacks and destroys anything else in the digestive tract within 2D6 hours; one with more Hit Points than it survives, and the ongoing fight gives the host cramps, -2 on all combat abilities.', 'Rifts World Book 21: Splynn Dimensional Market p.134-135', NULL),
  ('titanizer', 'Titanizer (Symbiote)', 'rifts', 'magic', NULL, 40000000, '40 million credits on average; the book says one may sell for a hundred million', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A hand-sized organism set near the heart, on the chest or back, that lives on the host''s P.P.E. and in return makes him a giant for short bursts; in the wild it did so only in danger, and now it builds laborers, soldiers and arena gladiators. Mortal hosts only, never an M.D.C. creature, supernatural being or creature of magic. It breeds up to once a year: it signals a mate by pheromones within 20 ft (6 m), links tentacles within 5 ft (1.5 m), and after 2D4 months one young is born. 4D6 Hit Points, tripled and turned to M.D.C. when Titanized; up to twenty years bonded, and young survive 1D6 years unbonded; low animal intelligence. Up to four times a day it releases the effect of the Giant spell (Rifts Federation of Magic) for five minutes: +10 ft (3 m) height and +1000 lbs (450 kg); Horror Factor of 13 or +4, the greater of the two; Hit Points and S.D.C. tripled and made M.D.C. (600 at most); P.S. +50% and supernatural (60 at most); +1 melee attack; +1 strike and parry; bio-regenerates 2D6 M.D.C. each melee round. Bonded, his P.P.E. is halved for good, a mage''s too. While Titanized he cannot draw on P.P.E., cast magic or use TW items, his clothes and armor tear apart, Spd is -20% and he is -3 to dodge, and no other symbiote or parasite power works, though their penalties still do. It is his weak point: killed mid-power, it drops him back to normal, weak and dazed for 2D6 minutes at -3 initiative, -2 strike, -3 parry and dodge and half Spd; hitting it takes a called shot at -3. It grows with him while Titanized. Surgery may do lasting harm (Surgery Penalty Table for body organisms, Rifts Atlantis p.114), as may killing it; dying of old age, it falls off harmlessly. It ignores other organisms, but a Mystic Leech starves it dead in 2D4+2 days.', 'Rifts World Book 21: Splynn Dimensional Market p.135-136', NULL),
  ('zembahk-appendage', 'Zembahk Appendage (Symbiote)', 'rifts', 'magic', NULL, 10000000, '10 to 20 million credits, by its powers and availability; rare', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'A lobotomized Zembahk mystic worm grafted onto the body, giving the powers of the Zembahk staves (Rifts Atlantis p.120-122), or custom ones for a price. Humans, D-Bees and other mortals; never M.D.C. D-Bees, supernatural creatures or creatures of magic. It can go anywhere: under the natural arm, in place of it (-35% to skills needing hands), or commonly by a shoulder blade so it can reach up beside the head. It cannot breed. A Mega-Damage creature of 70 M.D.C. that regenerates 2D6 a day; lives up to 150 years linked; no alignment, having no mind. Powers: any one of the many magic or psionic powers of the Zembahk staves; or up to six common spells of levels 1-8 at the strength of a 5th-level Line Walker (13 or better to save), with 80 P.P.E. the host may also draw on; or psionics at 6th-level Master Psychic strength, five Sensitive or Physical powers plus two Super-Psionic powers of choice, with 20 P.P.E. and 92 I.S.P. the host may also use. P.P.E. and I.S.P. return at 10 points an hour; each magic or psionic attack uses one of the host''s attacks, and at most two spells go off per melee round. No bonuses for the host beyond the powers; the worm is +4 on an automatic dodge against attacks on it, and a blow from it does only 1D6 S.D.C. with none of the host''s P.S. bonus. Wearing a brain-dead worm costs 1D4 P.B. and 1 M.A. It weighs about 6 to 10 lbs (2.7 to 4.5 kg) and is 3 to 5 ft (.9 to 1.5 m) long. Surgery leaves no lasting harm if it succeeds; a failure means one roll on the Surgery Penalty Table for body organisms, Rifts Atlantis p.114. It ignores other organisms.', 'Rifts World Book 21: Splynn Dimensional Market p.136-137', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 11 gear rows are in' AS assertion, count(*) AS got, 11 AS want
  FROM gear WHERE slug IN ('aqua-mask', 'electrone', 'line-feeder', 'musical-nymph', 'storm-breather', 'solara', 'storm-screamer', 'symbiotic-heart', 'thundergut', 'titanizer', 'zembahk-appendage') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~360-splynn-symbiotes.sql');
